SELECT items.item_id, items.itemcode, items.item_name, items.opening_stock, pur_qty_query.pur_qty, sales_qty_query.sales_qty, materials.mat_id, stock_in_item_total.st_in_qty, stock_out_item_total.st_out_qty, (Nz([opening_stock],0)+Nz([pur_qty],0)+Nz([st_in_qty],0))-(Nz([sales_qty],0)+Nz([st_out_qty],0)) AS balance_qty, items.material, items.item_sft, [sales_qty]*[item_sft] AS st_sft, materials.mat_pur_price, materials.unit, item_category.category, materials.material_name
FROM item_category INNER JOIN (materials INNER JOIN ((((items LEFT JOIN pur_qty_query ON items.item_id = pur_qty_query.item_id) LEFT JOIN sales_qty_query ON items.item_id = sales_qty_query.item_id) LEFT JOIN stock_in_item_total ON items.item_id = stock_in_item_total.item_id) LEFT JOIN stock_out_item_total ON items.item_id = stock_out_item_total.item_id) ON (materials.mat_id = items.material) AND (materials.mat_id = items.material)) ON item_category.cat_id = materials.category_id;

